import unittest

from timestamps import format_timestamp


class FormatTimestampTests(unittest.TestCase):
    def test_analytics_uses_shanghai_time(self):
        self.assertEqual(
            format_timestamp("2024-01-01T00:30:00+00:00", "analytics"),
            "2024-01-01 08:30",
        )

    def test_public_api_uses_utc(self):
        self.assertEqual(
            format_timestamp("2024-06-01T12:34:56+05:30", "public_api"),
            "2024-06-01 07:04",
        )

    def test_timestamp_can_cross_calendar_day(self):
        self.assertEqual(
            format_timestamp("2024-01-01T23:30:00-02:00", "analytics"),
            "2024-01-02 09:30",
        )

    def test_unknown_target_raises_value_error(self):
        with self.assertRaises(ValueError):
            format_timestamp("2024-01-01T00:00:00+00:00", "other")

    def test_timezone_is_required(self):
        with self.assertRaises(ValueError):
            format_timestamp("2024-01-01T00:00:00", "public_api")


if __name__ == "__main__":
    unittest.main()

