from datetime import datetime, timezone
from zoneinfo import ZoneInfo


def format_timestamp(iso_timestamp, target):
    """Convert an aware ISO 8601 timestamp to a project's display format."""
    if target == "analytics":
        target_timezone = ZoneInfo("Asia/Shanghai")
    elif target == "public_api":
        target_timezone = timezone.utc
    else:
        raise ValueError(f"unknown timestamp target: {target!r}")

    timestamp = datetime.fromisoformat(iso_timestamp)
    if timestamp.tzinfo is None or timestamp.utcoffset() is None:
        raise ValueError("iso_timestamp must include a timezone")

    return timestamp.astimezone(target_timezone).strftime("%Y-%m-%d %H:%M")
